const feed=document.querySelector('#feed');
function postHtml(p,i){return `<article class="post"><div class="post-header"><span class="avatar ${p.avatar}">${p.initials}</span><span><b>${p.name}</b><small>${p.time}</small></span><button class="post-menu">•••</button></div><div class="meal-image" style="background-image:${p.image}"><span class="meal-badge">${p.kind}</span></div><div class="post-body"><p class="post-text"><b>${p.meal}</b> — ${p.text}</p><div class="tag-row">${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div></div><div class="post-actions"><button class="like" data-index="${i}">♡ <span>${p.likes}</span></button><button class="comment">◌ ${p.comments}</button>${p.coach?'<span class="coach-seen">✓ Coach Jamie saw this</span>':''}</div></article>`}
function renderPosts(){const ad=`<article class="post sponsored-post"><div class="post-header"><span class="avatar avatar-object">🌞</span><span><b>Sunny Side Kitchen</b><small>Partner · Near Tanjong Pagar</small></span><span class="sponsor-label">SPONSORED</span></div><div class="sponsor-visual"><div class="sponsor-copy"><b>Lunch that loves you back.</b><small>Wholegrain bowls from $9.90</small></div><div class="sponsor-bowl">🥗</div></div><div class="post-body"><p class="post-text"><b>Circle perk:</b> Free delivery on your first balanced bowl this week.</p><div class="tag-row"><span class="tag">Restaurant partner</span><span class="tag">Wholegrains</span></div></div><div class="post-actions"><button>♡ 112</button><button class="comment">◌ 14</button><button class="deal-button" data-deal>View perk</button></div></article>`;const blog=`<article class="post blog-card"><div class="blog-cover"><span class="content-label">COMMUNITY BLOG</span><h3>How I stopped ordering “the usual”</h3><span class="read-time">4 min read · by Aisha R.</span></div><div class="post-body"><p class="post-text">Three tiny habits that made healthier hawker lunches feel automatic—not restrictive.</p></div><div class="post-actions"><button>♡ 68</button><button class="comment">◌ 12</button><button class="deal-button" data-read>Read story</button></div></article>`;const poll=`<article class="post poll-card"><span class="content-label">QUICK POLL · 184 VOTES</span><h3>Your hardest healthy swap when eating out?</h3><button class="poll-option" style="--poll:38%"><span>Less sauce</span></button><button class="poll-option" style="--poll:27%"><span>Skip the sweet drink</span></button><button class="poll-option" style="--poll:21%"><span>Choose wholegrains</span></button><button class="poll-option" style="--poll:14%"><span>Add vegetables</span></button></article>`;const recipe=`<article class="post recipe-card"><div class="recipe-grid"><div class="recipe-photo"></div><div class="recipe-copy"><span class="content-label">SAVEABLE RECIPE</span><h3>20-min rainbow bowls</h3><p>One tray, one grain, one bright dressing. Four lunches sorted.</p><div class="recipe-stats"><span>⏱ 20 min</span><span>♡ 4 servings</span></div><button class="text-button" data-save-recipe>Save recipe →</button></div></div></article>`;const win=`<article class="post win-card"><span class="content-label">CIRCLE CELEBRATION</span><div class="big-streak">30</div><h3>days of showing up 🎉</h3><p>Jules completed the Mindful Lunch challenge. 42 friends cheered.</p><button class="secondary-button" data-cheer>Send a cheer</button></article>`;const coach=`<article class="post coach-note"><span class="content-label">COACH JAMIE'S SUNDAY NOTE</span><blockquote>“A balanced week still has room for kaya toast. Consistency is not perfection.”</blockquote><footer>Jamie · Personal trainer & nutrition coach</footer><div class="tag-row"><span class="tag">Mindset</span><span class="tag">No guilt</span></div></article>`;feed.innerHTML=[postHtml(posts[0],0),blog,ad,postHtml(posts[1],1),poll,recipe,postHtml(posts[2],2),coach,win].join('');}
renderPosts();
const helpPostHtml=`<article class="post help-post" data-help-post><div class="post-header"><span class="avatar avatar-real avatar-nadia"></span><span><b>Sophie Lim</b><small>12 min ago · Asking the community</small></span><button class="post-menu" aria-label="Post options">•••</button></div><div class="help-copy"><span class="help-kicker">NEED ADVICE · REAL TALK</span><h3>I overate all weekend—how do I get back on track without gaining more?</h3><p>I feel bloated and tempted to skip meals until the scale drops. What would a calm, normal day of eating look like after a weekend like this? I want to recover without punishing myself or starting another restrict-and-overeat cycle.</p><div class="tag-row"><span class="tag">No crash diets</span><span class="tag">Back to routine</span><span class="tag">Please be kind</span></div></div><div class="post-actions"><button>♡ 39</button><button class="comment">◌ 24</button><button class="ugc-save" aria-label="Save post">⌑</button><button class="ugc-share" aria-label="Share post">↗</button></div></article>`;const ensureHelpPost=()=>{if(!feed.querySelector('[data-help-post]')&&feed.firstElementChild)feed.firstElementChild.insertAdjacentHTML('afterend',helpPostHtml)};ensureHelpPost();new MutationObserver(ensureHelpPost).observe(feed,{childList:true});
const jioBlogs=`<article class="post jio-card" data-blog="breakfast"><div class="jio-cover theme-breakfast"><span class="host-badge">👩🏻 Individual jio · 8 spots</span><h3>Wholemeal Breakfast Club</h3><p>Saturday · 9:00am · Tiong Bahru</p></div><div class="post-body"><p class="post-text"><b>Hosted by Chloe:</b> Bring one wholemeal breakfast idea and taste everyone’s favourite spreads.</p><div class="jio-meta"><span>♡ 46 interested</span><span>◌ 9 replies</span></div></div></article><article class="post jio-card" data-blog="mediterranean"><div class="jio-cover theme-med"><span class="host-badge">🍽️ Restaurant jio · Partner event</span><h3>Mediterranean Sharing Dinner</h3><p>Olive & Grain · Friday · 7:00pm</p></div><div class="post-body"><p class="post-text">A family-style Mediterranean table: olive oil, beans, fish, vegetables and good conversation.</p><div class="jio-meta"><span>♡ 82 interested</span><span>12 seats left</span></div></div></article><article class="post jio-card" data-blog="fasting"><div class="jio-cover theme-fasting"><span class="host-badge">🧑🏻‍⚕️ Dietitian guide</span><h3>Gentle Intermittent Fasting: Start with 12:12</h3><p>Practical guide · 6 min read</p></div><div class="post-body"><p class="post-text">How to plan eating windows without turning meals into a punishment.</p><div class="safety-note">Educational only. Not suitable for everyone, including pregnancy or some medical conditions.</div></div></article><article class="post jio-card" data-blog="anti"><div class="jio-cover theme-anti"><span class="host-badge">🥕 Pantry challenge</span><h3>A Week of Anti-Inflammatory Meals from Basic Ingredients</h3><p>Shopping list + 4 flexible meal formulas</p></div><div class="post-body"><p class="post-text">Oats, beans, frozen vegetables, eggs, ginger and olive oil—simple ingredients, many combinations.</p><div class="jio-meta"><span>♡ 127 saves</span><span>◌ 23 comments</span></div></div></article>`;
