const articleData={usual:{kicker:'COMMUNITY BLOG · EATING OUT',title:'How I stopped ordering “the usual”',author:'Aisha Rahman',lead:'I didn’t need a perfect meal plan. I needed three tiny pauses between seeing the menu and saying my order.',heads:['1. I chose before I reached the counter','2. I kept the food I actually liked','3. I celebrated the choice, not the calorie count']},breakfast:{kicker:'INDIVIDUAL FOOD JIO · WHOLEMEAL',title:'Wholemeal Breakfast Club',author:'Chloe Tan · Community host',lead:'A slow Saturday breakfast for swapping easy wholemeal ideas, favourite spreads and new friends.',heads:['What to bring','What we will make together','How to join the jio']},mediterranean:{kicker:'RESTAURANT JIO · MEDITERRANEAN',title:'Mediterranean Sharing Dinner',author:'Olive & Grain · Restaurant partner',lead:'One long table built around vegetables, beans, whole grains, olive oil, fish and conversation.',heads:['The shared menu','Why family-style works','Reserve your seat']},fasting:{kicker:'DIETITIAN GUIDE · INTERMITTENT FASTING',title:'Gentle Intermittent Fasting: Start with 12:12',author:'Lin Wei · Registered dietitian',lead:'Time-restricted eating can start gently: a consistent 12-hour overnight break is often more realistic than jumping into 16:8.',heads:['Start with your normal routine','Build satisfying meals','Know when to stop']},anti:{kicker:'PRACTICAL GUIDE · ANTI-INFLAMMATORY EATING',title:'A Week of Anti-Inflammatory Meals from Basic Ingredients',author:'Nadia · Home cook',lead:'You do not need specialty powders. Build flexible meals from oats, beans, vegetables, eggs, ginger and olive oil.',heads:['Six useful basics','Four mix-and-match formulas','Make it work all week']}};
const articleParagraphs={breakfast:['Meet at the community table with one topping or breakfast idea to share—fruit, nut butter, eggs or a favourite wholemeal loaf.','We will build toast boards, overnight oats and savoury egg sandwiches, then trade the easiest combinations.','Tap join, introduce yourself in the comments and tell the group about any dietary needs.'],mediterranean:['Expect hummus, lentil salad, grilled vegetables, fish, wholegrain flatbread and fruit—served in the middle for everyone to try.','Sharing several dishes makes vegetables and beans feel abundant, while everyone can choose portions that suit them.','The restaurant is holding 12 community seats. Join solo or bring a friend; the host will handle introductions.'],fasting:['Try finishing dinner and eating breakfast 12 hours later. Keep sleep, work and family routines in mind before extending the window.','During the eating window, prioritise protein, fibre, vegetables and enough energy. Fasting should not mean under-fuelling.','Stop if you feel unwell. Seek personalised medical advice if pregnant, under 18, managing diabetes, taking relevant medication or with an eating-disorder history.'],anti:['Keep oats, canned beans, frozen vegetables, eggs, ginger and olive oil on hand. Add fruit, nuts or fish when available.','Rotate four formulas: oats with fruit; bean-and-veg bowls; ginger egg stir-fries; and sheet-pan vegetables with a protein.','Batch one grain and one tray of vegetables, then change sauces and toppings so the week stays interesting.']};
articleData.bao={kicker:'REAL-LIFE FAT-LOSS FOOD · PORTIONS',title:'Foods That Look High-Calorie—but Can Fit a Fat-Loss Phase',author:'Jamie Wu · Home cook',lead:'Bao often gets labelled as an “off-limits” food, but a sensible portion with a lean, vegetable-rich filling can be satisfying and practical.',heads:['Start with the filling','Build a complete meal','Look at the whole day—not one food']};articleParagraphs.bao=['Choose buns with chicken, lean pork, tofu or plenty of vegetables when available. A filling with protein and vegetables generally keeps the meal more satisfying.','Try one bun with vegetables, soup or fruit instead of treating the bun as a snack before another full meal. Portion and the foods around it matter.','No single food determines fat loss. Regular portions, overall energy intake and habits across the week matter more than banning a familiar favourite.'];
