const modal=document.querySelector('#modalBackdrop');const openModal=()=>{modal.classList.add('open');modal.setAttribute('aria-hidden','false');setTimeout(()=>document.querySelector('#mealName').focus(),50)};const closeModal=()=>{modal.classList.remove('open');modal.setAttribute('aria-hidden','true')};['openPost','mobilePost','mobileShare'].forEach(id=>document.querySelector(`#${id}`)?.addEventListener('click',openModal));document.querySelector('#closeModal').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
