const chatBackdrop=document.querySelector('#chatBackdrop');const chatMessages=document.querySelector('#chatMessages');let activeChat='Lunch Break Club';function renderChat(name){activeChat=name;const chat=chats[name]||chats['Lunch Break Club'];document.querySelector('#chatTitle').textContent=name;document.querySelector('#chatIcon').textContent=chat.icon;document.querySelector('#chatStatus').textContent=chat.status;chatMessages.innerHTML=`<div class="chat-day">TODAY</div>`+chat.messages.map(([person,icon,message,time])=>`<div class="bubble-row ${person==='me'?'mine':''}"><span class="chat-avatar">${icon}</span><div class="bubble"><b>${person==='me'?'You':person}</b><p>${message}</p><small>${time}</small></div></div>`).join('');chatBackdrop.classList.add('open');chatBackdrop.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';chatMessages.scrollTop=chatMessages.scrollHeight}function closeChat(){chatBackdrop.classList.remove('open');chatBackdrop.setAttribute('aria-hidden','true');document.body.style.overflow=''}
