function loadArticle(card){const id=card.dataset.blog||'usual';const data=articleData[id];document.querySelector('#articleTitle').textContent=data.title;document.querySelector('.article-hero .content-label').textContent=data.kicker;document.querySelector('.author-line b').textContent=data.author;document.querySelector('.article-body .lead').textContent=data.lead;document.querySelectorAll('.article-body>h3').forEach((heading,index)=>{if(data.heads[index])heading.textContent=data.heads[index]});if(articleParagraphs[id])document.querySelectorAll('.article-body>p:not(.lead)').forEach((paragraph,index)=>paragraph.textContent=articleParagraphs[id][Math.min(index,2)]);document.querySelector('#posterTitle').textContent=data.title;openArticle()}
