articleData.french={kicker:'DINING CULTURE · FRENCH RESTAURANTS',title:'How to Order Like a Local at a French Restaurant',author:'Camille Laurent · Food writer',lead:'French dining feels much easier once you understand the rhythm of the menu. You do not need perfect pronunciation—curiosity and courtesy go further.',heads:['Start by reading the menu structure','Order with a few useful phrases','Enjoy the pace of the meal']};
articleData.etiquette={kicker:'SOCIAL GUIDE · TABLE MANNERS',title:'Modern Table Manners That Make Everyone Comfortable',author:'Amelia Hart · Hospitality educator',lead:'Good manners are less about rigid rules and more about helping everyone at the table feel considered, included and at ease.',heads:['Begin with the shared signals','Navigate communal dishes gracefully','Handle phones, timing and conversation']};
articleParagraphs.french=['Look for an entrée, plat and dessert. In France, entrée usually means the starter; a formule or prix fixe menu bundles courses at a set price.','Try “Je vais prendre…” followed by the dish, or ask “Qu’est-ce que vous recommandez?” for a recommendation. A friendly bonjour before ordering matters more than a flawless accent.','Courses are meant to arrive gradually. Follow the table’s pace, ask before changing a dish, and finish with coffee only if you want it—there is no test to pass.'];
articleParagraphs.etiquette=['Place your napkin on your lap after sitting. Wait until everyone is served, unless the host invites you to begin while a hot dish is ready.','Pass shared plates rather than reaching across people. Take a modest first portion so everyone can try it, then return for more when the dish comes around.','Keep your phone away unless the group agrees on photos. Include quieter guests, avoid commenting on what others eat, and let consideration—not perfection—guide you.'];
const culturePosts=`<article class="post jio-card" data-blog="french" role="button" tabindex="0" aria-label="Open full community blog post"><div class="jio-cover theme-french"><span class="host-badge">🥐 Dining culture · 5 min read</span><h3>How to Order Like a Local at a French Restaurant</h3><p>Menus, courses and useful phrases—without the awkwardness</p></div><div class="post-body"><p class="post-text">From reading prix fixe menus to asking for recommendations with confidence.</p><div class="jio-meta"><span>♡ 94 saves</span><span>◌ 18 comments</span></div></div></article><article class="post jio-card" data-blog="etiquette" role="button" tabindex="0" aria-label="Open full community blog post"><div class="jio-cover theme-etiquette"><span class="host-badge">🍽️ Social guide · Table manners</span><h3>Modern Table Manners That Make Everyone Comfortable</h3><p>A practical guide for shared meals and special occasions</p></div><div class="post-body"><p class="post-text">The small signals that help a table feel relaxed—from napkins to shared dishes.</p><div class="jio-meta"><span>♡ 121 saves</span><span>◌ 27 comments</span></div></div></article>`;
document.querySelector('[data-blog="anti"]').insertAdjacentHTML('beforebegin',culturePosts);

