document.querySelectorAll('.jio-card').forEach(card=>{const p=socialPostData[card.dataset.blog];if(!p)return;card.classList.add('ugc-post');card.innerHTML=`<div class="post-header"><span class="avatar ${p.avatar}">${p.emoji||''}</span><span><b>${p.name}${p.verified?' <i class="verified">✓</i>':''}</b><small>${p.time}</small></span><button class="post-menu" aria-label="Post options">•••</button></div><div class="ugc-image" style="background-image:url('${p.image}')"><span>${p.label}</span></div><div class="post-body"><p class="ugc-title">${p.title}</p><p class="post-text">${p.caption}</p><div class="tag-row">${p.tags.map(tag=>`<span class="tag">${tag}</span>`).join('')}</div></div><div class="post-actions"><button class="ugc-like">♡ <span>${p.likes}</span></button><button class="ugc-comment">◌ ${p.comments}</button><button class="ugc-save" aria-label="Save post">⌑</button><button class="ugc-share" aria-label="Share post">↗</button></div>`});
feed.addEventListener('click',event=>{const action=event.target.closest('.ugc-like,.ugc-comment,.ugc-save,.ugc-share,.post-menu');if(!action)return;event.stopImmediatePropagation();if(action.classList.contains('ugc-like')){action.classList.toggle('liked');const count=action.querySelector('span');count.textContent=String(Number(count.textContent)+(action.classList.contains('liked')?1:-1));action.firstChild.textContent=action.classList.contains('liked')?'♥ ':'♡ '}else if(action.classList.contains('ugc-comment')){const card=action.closest('.jio-card');loadArticle(card);setTimeout(()=>document.querySelector('#comments').scrollIntoView({behavior:'smooth'}),100)}else if(action.classList.contains('ugc-save')){action.textContent='✓';toast('Post saved')}else if(action.classList.contains('ugc-share')){loadArticle(action.closest('.jio-card'));setTimeout(openPoster,100)}else toast('Post options opened')},true);

const createBackdrop=document.querySelector('#createBackdrop');const postBackdrop=document.querySelector('#postBackdrop');
function showLayer(layer){layer.classList.add('open');layer.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}function hideLayer(layer){layer.classList.remove('open');layer.setAttribute('aria-hidden','true');document.body.style.overflow=''}
document.querySelector('#mobileProfile').addEventListener('click',()=>switchView('profile'));document.querySelector('#trophyProfile').addEventListener('click',()=>switchView('profile'));document.querySelector('.profile-row').addEventListener('click',()=>switchView('profile'));
document.querySelector('#mobileShare').addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();showLayer(createBackdrop)},true);document.querySelector('#closeCreate').addEventListener('click',()=>hideLayer(createBackdrop));createBackdrop.addEventListener('click',event=>{if(event.target===createBackdrop)hideLayer(createBackdrop)});
document.querySelector('#choosePost').addEventListener('click',()=>{hideLayer(createBackdrop);showLayer(postBackdrop);setTimeout(()=>document.querySelector('#postCaption').focus(),80)});document.querySelector('#chooseMeal').addEventListener('click',()=>{hideLayer(createBackdrop);openModal()});document.querySelector('#closePostComposer').addEventListener('click',()=>hideLayer(postBackdrop));postBackdrop.addEventListener('click',event=>{if(event.target===postBackdrop)hideLayer(postBackdrop)});
let postPhotoAsset='assets/avocado-toast.png';let selectedPhotoUrl='';const postPhotoInput=document.querySelector('#postPhotoInput');const postPhotoStatus=document.querySelector('#postPhotoStatus');document.querySelector('#postPhoto').addEventListener('click',event=>{event.preventDefault();postPhotoInput.click()});postPhotoInput.addEventListener('change',()=>{const files=[...postPhotoInput.files];if(!files.length)return;if(selectedPhotoUrl)URL.revokeObjectURL(selectedPhotoUrl);selectedPhotoUrl=URL.createObjectURL(files[0]);postPhotoAsset=selectedPhotoUrl;document.querySelector('.photo-preview').style.backgroundImage=`url('${postPhotoAsset}')`;postPhotoStatus.textContent=files.length===1?files[0].name:`${files.length} photos selected`;document.querySelector('#postPhoto').classList.add('has-photo');toast(files.length===1?'Photo selected':`${files.length} photos selected`)});
const safeText=value=>value.replace(/[<>&]/g,'');
document.querySelector('#publishPost').addEventListener('click',()=>{const caption=document.querySelector('#postCaption').value.trim();if(!caption){toast('Write a caption first');return}const audience=document.querySelector('#postAudience').value;feed.insertAdjacentHTML('afterbegin',`<article class="post fresh-post"><div class="post-header"><span class="avatar avatar-photo avatar-2"></span><span><b>Alex Yap</b><small>Just now · ${audience}</small></span><button class="post-menu">•••</button></div><div class="ugc-image" style="background-image:url('${postPhotoAsset}')"></div><div class="post-body"><p class="post-text">${safeText(caption)}</p></div><div class="post-actions"><button class="new-like">♡ <span>0</span></button><button>◌ 0</button><button class="ugc-save" style="margin-left:auto">⌑</button><button>↗</button></div></article>`);document.querySelector('#postCaption').value='';postPhotoStatus.textContent='Tap to choose from your library';document.querySelector('#postPhoto').classList.remove('has-photo');postPhotoInput.value='';hideLayer(postBackdrop);switchView('feed');toast('Your post is live ✦')});
document.querySelector('#publishMeal').addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();const name=document.querySelector('#mealName').value.trim();if(!name){toast('Add a meal name first');return}const note=document.querySelector('#mealNote').value.trim()||'Logged this meal to keep my day on track.';const circle=document.querySelector('#shareCircle').value;const tags=[...document.querySelectorAll('.swap-chips .selected')].map(item=>item.textContent);feed.insertAdjacentHTML('afterbegin',`<article class="post fresh-post meal-record"><div class="post-header"><span class="avatar avatar-photo avatar-2"></span><span><b>Alex Yap</b><small>Just now · ${circle}</small></span><button class="post-menu">•••</button></div><div class="ugc-image" style="background-image:url('assets/bibimbap.png')"><span>Nutrition estimated</span></div><div class="post-body"><p class="ugc-title">${safeText(name)}</p><p class="post-text">${safeText(note)}</p><div class="meal-estimate-row"><span><b>~640</b> kcal</span><span><b>28g</b> protein</span><span><b>9g</b> fibre</span></div><div class="tag-row">${(tags.length?tags:['Meal logged']).map(tag=>`<span class="tag">${tag}</span>`).join('')}</div></div><div class="post-actions"><button class="new-like">♡ <span>0</span></button><button>◌ 0</button><span class="coach-seen">✓ Added to tracker</span></div></article>`);closeModal();switchView('feed');document.querySelector('#mealName').value='';document.querySelector('#mealNote').value='';toast('Meal logged and shared ✦')},true);
feed.addEventListener('click',event=>{const like=event.target.closest('.new-like');if(!like)return;like.classList.toggle('liked');const count=like.querySelector('span');count.textContent=like.classList.contains('liked')?'1':'0';like.firstChild.textContent=like.classList.contains('liked')?'♥ ':'♡ '});document.querySelector('#mealPhoto').addEventListener('click',()=>toast('Meal photo selected'));document.querySelectorAll('.profile-tabs button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.profile-tabs button').forEach(item=>item.classList.remove('active'));button.classList.add('active');toast(`${button.textContent} view`)}));document.querySelector('.profile-edit').addEventListener('click',()=>toast('Profile editor opened'));document.querySelectorAll('.profile-grid button').forEach(button=>button.addEventListener('click',()=>toast(button.getAttribute('aria-label'))));

const detailView=document.querySelector('#detailView');const postDetail=document.querySelector('#postDetail');let feedScrollPosition=0;
function enhanceFeedPosts(){document.querySelectorAll('#feed .post').forEach(card=>{card.setAttribute('role','button');card.tabIndex=0;card.setAttribute('aria-label',`Open post: ${card.querySelector('.ugc-title,h3,.post-text b')?.textContent||'community post'}`)})}
function detailImage(card){const image=card.querySelector('.ugc-image,.meal-image,.recipe-photo');if(image)return getComputedStyle(image).backgroundImage.replaceAll('"',"'");if(card.classList.contains('blog-card'))return `url('assets/jio-anti-inflammatory.png')`;if(card.classList.contains('sponsored-post'))return `url('assets/meal-prep.png')`;return ''}
function renderPostPage(card){feedScrollPosition=window.scrollY;const blogId=card.dataset.blog;const data=blogId?articleData[blogId]:null;const avatar=card.querySelector('.post-header .avatar');const author=card.querySelector('.post-header b')?.textContent||data?.author||card.querySelector('footer')?.textContent||'Plateful community';const meta=card.querySelector('.post-header small')?.textContent||'Shared today';const title=card.querySelector('.ugc-title')?.textContent||card.querySelector('.post-text b')?.textContent||card.querySelector('h3')?.textContent||card.querySelector('blockquote')?.textContent||'Community update';const body=card.querySelector('.ugc-title')?.nextElementSibling?.textContent||card.querySelector('.post-text')?.textContent||card.querySelector('blockquote')?.textContent||card.querySelector('p:not(.eyebrow)')?.textContent||'A small update shared with the Plateful community.';const image=detailImage(card);const likeText=card.querySelector('.like span,.ugc-like span,.post-actions button span')?.textContent||'24';const commentMatch=card.textContent.match(/(\d+)\s*(comments|replies)/i);const comments=commentMatch?.[1]||card.querySelector('.comment,.ugc-comment')?.textContent.match(/\d+/)?.[0]||'6';const avatarHtml=avatar?`<span class="${avatar.className}">${avatar.textContent}</span>`:'<span class="avatar avatar-real avatar-jules"></span>';let article='';if(data){const paragraphs=articleParagraphs[blogId]||[];article=`<div class="detail-article"><p>${data.lead}</p>${data.heads.map((heading,index)=>`<h2>${heading}</h2><p>${paragraphs[index]||'Small, practical choices are easier to repeat when they fit real life and can be shared with other people.'}</p>`).join('')}</div>`}postDetail.innerHTML=`<div class="detail-author">${avatarHtml}<span><b>${author}</b><small>${meta}</small></span><button class="detail-follow">Follow</button></div>${image&&image!=='none'?`<div class="detail-media" style="background-image:${image}"></div>`:'<div class="detail-empty-media">✦</div>'}<div class="detail-copy"><h1>${title}</h1><p>${body}</p><div class="tag-row">${[...card.querySelectorAll('.tag')].map(tag=>`<span class="tag">${tag.textContent}</span>`).join('')}</div></div><div class="detail-stats"><span><b>${likeText}</b> likes</span><span><b>${comments}</b> comments</span></div><div class="detail-actions"><button data-detail-like>♡ Like</button><button data-detail-comment>◌ Comment</button><button data-detail-save>⌑ Save</button><button data-detail-share>↗ Share</button></div>${article}<section class="detail-comments"><h3>Conversation</h3><div id="detailCommentList"><div class="detail-comment"><span class="avatar avatar-real avatar-maya"></span><div><b>Maya Chen</b><p>This is exactly the kind of realistic idea I can use this week.</p><small>12 min ago · ♡ 3</small></div></div><div class="detail-comment"><span class="avatar avatar-real avatar-ryan"></span><div><b>Ryan Koh</b><p>Saved this—and sending it to our circle.</p><small>4 min ago · ♡ 1</small></div></div></div><form class="detail-comment-form" id="detailCommentForm"><input id="detailCommentInput" placeholder="Join the conversation…" aria-label="Add a comment"><button class="primary-button" type="submit">Post</button></form></section>`;switchView('detail')}
feed.addEventListener('click',event=>{if(event.target.closest('button,input,textarea,select,a'))return;const card=event.target.closest('.post');if(!card)return;event.preventDefault();event.stopImmediatePropagation();renderPostPage(card)},true);feed.addEventListener('keydown',event=>{if(event.key!=='Enter'||event.target.closest('button,input,textarea,select,a'))return;const card=event.target.closest('.post');if(card){event.preventDefault();event.stopImmediatePropagation();renderPostPage(card)}},true);
document.querySelector('#detailBack').addEventListener('click',()=>{switchView('feed');requestAnimationFrame(()=>window.scrollTo({top:feedScrollPosition,behavior:'auto'}))});document.querySelector('#detailMore').addEventListener('click',()=>toast('Post options opened'));
postDetail.addEventListener('click',event=>{if(event.target.closest('.detail-follow')){event.target.textContent=event.target.textContent==='Following'?'Follow':'Following';return}if(event.target.closest('[data-detail-like]')){const button=event.target.closest('button');button.classList.toggle('active');button.textContent=button.classList.contains('active')?'♥ Liked':'♡ Like';return}if(event.target.closest('[data-detail-save]')){event.target.closest('button').textContent='✓ Saved';toast('Post saved');return}if(event.target.closest('[data-detail-share]')){toast('Share options opened');return}if(event.target.closest('[data-detail-comment]'))document.querySelector('#detailCommentInput').focus()});postDetail.addEventListener('submit',event=>{if(event.target.id!=='detailCommentForm')return;event.preventDefault();const input=document.querySelector('#detailCommentInput');const value=input.value.trim();if(!value)return;document.querySelector('#detailCommentList').insertAdjacentHTML('beforeend',`<div class="detail-comment"><span class="avatar avatar-photo avatar-2"></span><div><b>Alex Yap</b><p>${safeText(value)}</p><small>Just now · ♡ 0</small></div></div>`);input.value='';toast('Comment posted')});
enhanceFeedPosts();new MutationObserver(enhanceFeedPosts).observe(feed,{childList:true});
